import{I as i,o as h,c,j as s,a as n,J as e,w as l,b6 as d}from"./chunks/framework.COUcLbTA.js";const g={style:{margin:"50px 0"}},m=JSON.parse('{"title":"写代码时遇到错误怎么办 - 截图问 AI 的实战指南","description":"学习如何高效地向 AI 提问来解决开发中的各种报错问题，掌握截图、描述、定位问题的标准流程，让 AI 成为你的调试助手。","frontmatter":{"title":"写代码时遇到错误怎么办 - 截图问 AI 的实战指南","description":"学习如何高效地向 AI 提问来解决开发中的各种报错问题，掌握截图、描述、定位问题的标准流程，让 AI 成为你的调试助手。"},"headers":[],"relativePath":"zh-cn/stage-1/appendix-b-common-errors/index.md","filePath":"zh-cn/stage-1/appendix-b-common-errors/index.md"}'),k={name:"zh-cn/stage-1/appendix-b-common-errors/index.md"},y=Object.assign(k,{setup(b){const p="约 <strong>30 分钟</strong>";return(u,a)=>{const t=i("ChapterIntroduction"),o=i("StepBar"),r=i("ClientOnly");return h(),c("div",null,[a[1]||(a[1]=s("h1",{id:"写代码时遇到错误怎么办",tabindex:"-1"},[n("写代码时遇到错误怎么办 "),s("a",{class:"header-anchor",href:"#写代码时遇到错误怎么办","aria-label":"Permalink to “写代码时遇到错误怎么办”"},"​")],-1)),a[2]||(a[2]=s("h2",{id:"本章导读",tabindex:"-1"},[n("本章导读 "),s("a",{class:"header-anchor",href:"#本章导读","aria-label":"Permalink to “本章导读”"},"​")],-1)),e(t,{duration:p,tags:["调试技巧","AI 协作","问题排查","开发者工具"],coreOutput:"一套标准化的报错排查流程",expectedOutput:"能独立解决 90% 的常见报错"},{default:l(()=>[...a[0]||(a[0]=[s("p",null,"在 AI 时代，排查错误的方式已经变了。",-1),s("p",null,"你不需要背下所有错误类型，不需要成为调试专家，甚至不需要理解错误是什么意思。",-1),s("p",null,[s("strong",null,"你只需要学会一件事：怎么问 AI。")],-1),s("p",null,[n("本章会教你一套"),s("strong",null,"从简单到进阶"),n("的排查流程：")],-1),s("ol",null,[s("li",null,[s("strong",null,"第一步：直接问"),n("：描述现象 + 截图，一句话提问")]),s("li",null,[s("strong",null,"第二步：补充信息"),n("：如果解决不了，再打开 F12 补充关键信息")])],-1),s("p",null,[n("掌握这套流程后，"),s("strong",null,"90% 的报错你都能自己解决"),n("。")],-1)])]),_:1}),a[3]||(a[3]=s("div",{class:"info custom-block"},[s("p",{class:"custom-block-title"},"说明"),s("p",null,"本章所有方法基于 Cursor/Trae/Claude 等 AI IDE 的实际使用经验，可直接应用于日常开发。")],-1)),s("div",g,[e(r,null,{default:l(()=>[e(o,{active:0,items:[{title:"直接提问",description:"描述现象 + 截图"},{title:"补充信息",description:"打开 F12 定位问题"},{title:"迭代解决",description:"直到问题解决"}]})]),_:1})]),a[4]||(a[4]=d(`<h2 id="_1-核心心法-截图问-ai" tabindex="-1">1. 核心心法：截图问 AI <a class="header-anchor" href="#_1-核心心法-截图问-ai" aria-label="Permalink to “1. 核心心法：截图问 AI”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">为什么这一章很重要？</p><p>很多初学者遇到报错时的第一反应是：</p><ul><li>慌张，开始瞎改代码</li><li>花半小时搜索&quot;xxx 错误怎么解决&quot;</li><li>试图自己理解错误是什么意思</li><li>自己 debug 到深夜</li></ul><p><strong>这些都是在浪费时间。</strong></p><p>在 AI 时代，调试已经变成了一件很简单的事：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>看到报错 → 截图 → 问 AI → 按 AI 说的做</span></span></code></pre></div><p>你不需要理解错误，不需要会调试，甚至不需要知道问题出在哪里。</p><p><strong>你只需要学会怎么问。</strong></p></div><h3 id="_1-1-最简单的提问方式" tabindex="-1">1.1 最简单的提问方式 <a class="header-anchor" href="#_1-1-最简单的提问方式" aria-label="Permalink to “1.1 最简单的提问方式”">​</a></h3><p>不需要复杂的模板，两种方式任选：</p><p><strong>方式一：描述现象</strong></p><p>格式：刚才做了什么，现在出现了什么</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>刚才我修改了登录页面的代码，现在页面白屏了，怎么办？</span></span></code></pre></div><p><strong>方式二：截图</strong></p><p>直接截图当前页面或报错信息</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[截图]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这个报错怎么解决？</span></span></code></pre></div><p><strong>最好的方式：描述 + 截图</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>刚才我修改了登录页面的代码，现在页面白屏了。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[截图]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>怎么办？</span></span></code></pre></div><p><strong>记住：描述清楚上下文，加上截图，AI 能更快帮你解决问题。</strong></p><h3 id="_1-2-如何把问题讲清楚" tabindex="-1">1.2 如何把问题讲清楚 <a class="header-anchor" href="#_1-2-如何把问题讲清楚" aria-label="Permalink to “1.2 如何把问题讲清楚”">​</a></h3><p>很多初学者知道要提问，但不知道怎么说。其实只需要讲清楚三件事：</p><p><strong>1. 刚才做了什么</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>刚才我点击了保存按钮</span></span>
<span class="line"><span>刚才我修改了登录页面的代码</span></span>
<span class="line"><span>刚才我刷新了页面</span></span></code></pre></div><p><strong>2. 现在看到了什么</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>现在页面是空白的</span></span>
<span class="line"><span>现在按钮点了没反应</span></span>
<span class="line"><span>现在显示报错信息</span></span></code></pre></div><p><strong>3. 想要达到什么效果</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我想让数据保存成功</span></span>
<span class="line"><span>我想让页面正常显示</span></span>
<span class="line"><span>我想让按钮点击后弹出提示</span></span></code></pre></div><p><strong>完整示例：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>刚才我点击了保存按钮，现在页面显示&quot;保存失败&quot;的报错。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[截图]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>我想让表单数据成功保存到数据库，该怎么办？</span></span></code></pre></div><p><strong>关键原则：</strong></p><ul><li>用大白话描述，不用专业术语</li><li>按时间顺序说：先做了什么，然后发生了什么</li><li>把你的预期说出来，让 AI 知道你想要什么</li></ul><h2 id="_2-第一步-直接描述现象提问" tabindex="-1">2. 第一步：直接描述现象提问 <a class="header-anchor" href="#_2-第一步-直接描述现象提问" aria-label="Permalink to “2. 第一步：直接描述现象提问”">​</a></h2><p>遇到问题时，<strong>不要急着打开 F12</strong>。先直接描述现象，截图当前页面，丢给 AI 看看。</p><p>很多时候，AI 看到截图就能直接给出解决方案。</p><h3 id="_2-1-常见现象怎么描述" tabindex="-1">2.1 常见现象怎么描述 <a class="header-anchor" href="#_2-1-常见现象怎么描述" aria-label="Permalink to “2.1 常见现象怎么描述”">​</a></h3><div class="tip custom-block"><p class="custom-block-title">直接描述即可</p><p><strong>页面白屏</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>页面打开是空白的，怎么办？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[截图]</span></span></code></pre></div><p><strong>按钮点击没反应</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>点击这个按钮没反应，帮我看看。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[截图]</span></span></code></pre></div><p><strong>数据保存不了</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>点了保存，数据没存上，怎么办？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[截图]</span></span></code></pre></div><p><strong>样式显示不对</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>这个按钮位置偏了，怎么调整？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[截图]</span></span></code></pre></div><p><strong>接口报错</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>调用接口报错了，帮我看看。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[截图]</span></span></code></pre></div></div><h3 id="_2-2-如果-ai-直接解决了" tabindex="-1">2.2 如果 AI 直接解决了 <a class="header-anchor" href="#_2-2-如果-ai-直接解决了" aria-label="Permalink to “2.2 如果 AI 直接解决了”">​</a></h3><p>恭喜你，问题解决了！按照 AI 说的修改即可。</p><h3 id="_2-3-如果-ai-说-需要更多信息" tabindex="-1">2.3 如果 AI 说&quot;需要更多信息&quot; <a class="header-anchor" href="#_2-3-如果-ai-说-需要更多信息" aria-label="Permalink to “2.3 如果 AI 说&quot;需要更多信息&quot;”">​</a></h3><p>这时候才需要打开 F12，补充关键信息。往下看。</p><h2 id="_3-第二步-补充关键信息" tabindex="-1">3. 第二步：补充关键信息 <a class="header-anchor" href="#_3-第二步-补充关键信息" aria-label="Permalink to “3. 第二步：补充关键信息”">​</a></h2><p>当 AI 说需要更多信息时，根据问题类型，打开 F12 截取对应的内容。</p><h3 id="_3-1-什么时候需要补充信息" tabindex="-1">3.1 什么时候需要补充信息 <a class="header-anchor" href="#_3-1-什么时候需要补充信息" aria-label="Permalink to “3.1 什么时候需要补充信息”">​</a></h3><p>AI 可能会这样回复：</p><ul><li>&quot;请打开 Console 看看有没有报错&quot;</li><li>&quot;截图 Network 面板给我看看&quot;</li><li>&quot;需要看具体的错误信息&quot;</li></ul><p>这时候，根据下面的指引补充截图。</p><h3 id="_3-2-补充-console-信息-页面白屏-报错" tabindex="-1">3.2 补充 Console 信息（页面白屏/报错） <a class="header-anchor" href="#_3-2-补充-console-信息-页面白屏-报错" aria-label="Permalink to “3.2 补充 Console 信息（页面白屏/报错）”">​</a></h3><div class="tip custom-block"><p class="custom-block-title">操作步骤</p><p><strong>第一步：按 F12 打开开发者工具</strong></p><p>Mac 是 <code>Cmd+Option+I</code>，或者右键页面选&quot;检查&quot;。</p><p><strong>第二步：切换到 Console 标签页</strong></p><p><strong>第三步：截图红色报错信息</strong></p><p><strong>第四步：发给 AI</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Console 报错如下：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[截图]</span></span></code></pre></div></div><h3 id="_3-3-补充-network-信息-数据问题-api-报错" tabindex="-1">3.3 补充 Network 信息（数据问题/API 报错） <a class="header-anchor" href="#_3-3-补充-network-信息-数据问题-api-报错" aria-label="Permalink to “3.3 补充 Network 信息（数据问题/API 报错）”">​</a></h3><div class="tip custom-block"><p class="custom-block-title">操作步骤</p><p><strong>第一步：按 F12 打开开发者工具</strong></p><p><strong>第二步：切换到 Network 标签页</strong></p><p><strong>第三步：重新操作一遍</strong>（点保存/刷新页面）</p><p><strong>第四步：找到对应请求，截图</strong></p><ul><li>看 URL 和状态码</li><li>看 Payload（传的参数）</li><li>看 Response（返回结果）</li></ul><p><strong>第五步：发给 AI</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Network 信息如下：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请求：[截图1]</span></span>
<span class="line"><span>参数：[截图2]</span></span>
<span class="line"><span>返回：[截图3]</span></span></code></pre></div></div><h3 id="_3-4-补充-elements-信息-样式问题" tabindex="-1">3.4 补充 Elements 信息（样式问题） <a class="header-anchor" href="#_3-4-补充-elements-信息-样式问题" aria-label="Permalink to “3.4 补充 Elements 信息（样式问题）”">​</a></h3><div class="tip custom-block"><p class="custom-block-title">操作步骤</p><p><strong>第一步：右键元素 → &quot;检查&quot;</strong></p><p>开发者工具会自动定位到该元素。</p><p><strong>第二步：截图 Styles 面板</strong></p><p><strong>第三步：发给 AI</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>元素样式如下：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[截图]</span></span></code></pre></div></div><h2 id="_4-第三步-迭代直到解决" tabindex="-1">4. 第三步：迭代直到解决 <a class="header-anchor" href="#_4-第三步-迭代直到解决" aria-label="Permalink to “4. 第三步：迭代直到解决”">​</a></h2><h3 id="_4-1-低效的做法" tabindex="-1">4.1 低效的做法 <a class="header-anchor" href="#_4-1-低效的做法" aria-label="Permalink to “4.1 低效的做法”">​</a></h3><p>这些做法会浪费你的时间：</p><p>看到报错就慌张，开始瞎改代码 花半小时搜索错误解决方案 试图自己理解每个错误的意思 一个人 debug 到深夜</p><h3 id="_4-2-高效的做法" tabindex="-1">4.2 高效的做法 <a class="header-anchor" href="#_4-2-高效的做法" aria-label="Permalink to “4.2 高效的做法”">​</a></h3><p>按照这套流程来：</p><p>先直接描述现象截图提问 AI 说需要更多信息时，再打开 F12 补充 按照建议修改代码 改完后测试，如果问题还在就继续截图提问</p><h2 id="_5-总结-完整流程" tabindex="-1">5. 总结：完整流程 <a class="header-anchor" href="#_5-总结-完整流程" aria-label="Permalink to “5. 总结：完整流程”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>遇到问题</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>直接描述现象 + 截图</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>丢给 AI：&quot;怎么办？&quot;</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>AI 直接解决？</span></span>
<span class="line"><span>    ↓ 是</span></span>
<span class="line"><span>按 AI 说的做</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>测试是否解决</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>    ↓ 否 / AI 需要更多信息</span></span>
<span class="line"><span>打开 F12，补充关键信息</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>再发给 AI</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>重复直到解决</span></span></code></pre></div>`,55))])}}});export{m as __pageData,y as default};
